def compute(vars):
    total_goodwill_acquired = vars["v1"]
    bolts_goodwill_acquired = vars["v2"]
    value = total_goodwill_acquired - bolts_goodwill_acquired
    return {
        "value": value,
        "trace": {
            "total_goodwill_acquired": total_goodwill_acquired,
            "bolts_goodwill_acquired": bolts_goodwill_acquired,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
